  CONSTRAINT `employees_ibfk_2` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`),
  CONSTRAINT `employees_ibfk_3` FOREIGN KEY (`atasan_langsung_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL
